#!/usr/bin/env node
/**
 * Generates the i18n registry files under `i18n/generated/` from the locale
 * list in `i18n/locales.ts` (MM51). After this, registering a locale is:
 *
 *   1. add its row to `i18n/locales.ts`;
 *   2. copy `i18n/locales/en-us/` to `i18n/locales/<code lowercased>/`
 *      (without the English-only `interface/metadata.json`);
 *   3. `npm run i18n:gen`.
 *
 * Outputs (all checked in, all "DO NOT EDIT"):
 *   - resources.generated.ts     the DEFAULT locale's client-eager shards
 *                                (interface/_core, components, tools;
 *                                error/_core; accessibility/_core,
 *                                components) for `i18n/resources.ts`. Only
 *                                English ships in the client bundle; every
 *                                other locale's eager bundle reaches the
 *                                browser as a layout prop (see
 *                                `i18n/localeResources.ts`), so adding a
 *                                locale does not grow first-load JS.
 *   - shardLoaders.generated.ts  lazy `import()` of interface/forms + panels
 *                                per locale, for `lib/i18n/ensureShard.ts`
 *   - serverBundles.generated.ts all ten shards per locale, for the server
 *                                components (`lib/i18n/server.tsx`)
 *   - toolPages.generated.ts     the optional per-locale `toolPages.ts`
 *                                overrides, for `i18n/toolPageContent.ts`
 *   - translatorShards.generated.ts  lazy `import()` of every editable shard
 *                                per locale (MM53). Imported ONLY by
 *                                `lib/translator/shardSource.ts`, which only a
 *                                translator deployment loads; a production
 *                                build never reaches it.
 *
 * `render()` is pure so `i18n/generated/registry.test.ts` can compare its
 * output with the checked-in files (the staleness test).
 *
 * Run: npm run i18n:gen          (write)
 *      npm run i18n:gen -- --check   (exit 1 if any file is stale; for CI)
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

export const GENERATED_DIR = 'i18n/generated';

/** Shards merged into the client i18next instance at init. */
export const EAGER_SHARDS = [
  'interface/_core',
  'interface/components',
  'interface/tools',
  'error/_core',
  'accessibility/_core',
  'accessibility/components',
];

/** Shards merged lazily, inside the dynamic import of a tool panel. */
export const LAZY_SHARDS = ['interface/forms', 'interface/panels'];

/** Every shard a server component can read. */
export const SERVER_SHARDS = [
  'interface/_core',
  'interface/pages',
  'interface/forms',
  'interface/panels',
  'interface/components',
  'interface/tools',
  'interface/articles',
  'error/_core',
  'accessibility/_core',
  'accessibility/components',
];

/**
 * Every shard a translator can edit (MM53): the server set plus the email copy
 * the API's email generator reads. `interface/metadata.json` is English-only.
 */
export const TRANSLATOR_SHARDS = [...SERVER_SHARDS, 'interface/email'];

const HEADER = [
  '// DO NOT EDIT — generated by scripts/gen-i18n-registry.mjs from i18n/locales.ts.',
  '// Run `npm run i18n:gen` after adding, removing or renaming a locale.',
];

/** `"zh-CN"` → `"zh-cn"`, the locale directory name. */
export const codeToDir = (code) => code.toLowerCase();

const pascal = (s) =>
  s
    .split(/[-_/]+/)
    .filter(Boolean)
    .map((p) => p[0].toUpperCase() + p.slice(1).toLowerCase())
    .join('');

/** `("zh-CN", "interface/_core")` → `"zhCnInterfaceCore"`. */
const ident = (code, suffix) => {
  const name = pascal(code) + pascal(suffix);
  return name[0].toLowerCase() + name.slice(1);
};

const shardPath = (code, shard) => `../locales/${codeToDir(code)}/${shard}.json`;

function importBlock(codes, shards) {
  const lines = [];
  for (const code of codes) {
    for (const shard of shards) {
      lines.push(`import ${ident(code, shard)} from "${shardPath(code, shard)}";`);
    }
  }
  return lines;
}

function shardMap(name, codes, shards) {
  const lines = [
    '/** locale code → shard path (no `.json`) → parsed shard. */',
    `export const ${name}: Record<string, Record<string, Record<string, unknown>>> = {`,
  ];
  for (const code of codes) {
    lines.push(`  "${code}": {`);
    for (const shard of shards) lines.push(`    "${shard}": ${ident(code, shard)},`);
    lines.push('  },');
  }
  lines.push('};');
  return lines;
}

function renderResources(defaultCode) {
  return [
    ...HEADER,
    '//',
    '// The default locale\'s client-eager shards, consumed only by `i18n/resources.ts`.',
    '// Other locales are deliberately absent: see `i18n/localeResources.ts`.',
    '',
    ...importBlock([defaultCode], EAGER_SHARDS),
    '',
    `export const defaultLocaleCode = "${defaultCode}";`,
    '',
    '/** shard path (no `.json`) → parsed shard. */',
    'export const defaultEagerShards: Record<string, Record<string, unknown>> = {',
    ...EAGER_SHARDS.map((shard) => `  "${shard}": ${ident(defaultCode, shard)},`),
    '};',
    '',
  ].join('\n');
}

function renderShardLoaders(codes) {
  const lines = [
    ...HEADER,
    '//',
    '// Lazy forms/panels loaders per locale, consumed only by `lib/i18n/ensureShard.ts`.',
    '// Each `import()` keeps one locale\'s JSON in its own lazy chunk.',
    '',
    'export type ShardModule = { default: Record<string, unknown> };',
    '',
    'export const SHARD_LOADERS: Record<string, () => Promise<[ShardModule, ShardModule]>> = {',
  ];
  for (const code of codes) {
    lines.push(`  "${code}": () =>`);
    lines.push('    Promise.all([');
    for (const shard of LAZY_SHARDS) lines.push(`      import("${shardPath(code, shard)}"),`);
    lines.push('    ]),');
  }
  lines.push('};', '');
  return lines.join('\n');
}

function renderServerBundles(codes) {
  return [
    ...HEADER,
    '//',
    '// Every shard of every locale, for SERVER COMPONENTS ONLY (`lib/i18n/server.tsx`).',
    '// Importing this from a client module would put every locale into the browser.',
    '',
    ...importBlock(codes, SERVER_SHARDS),
    '',
    ...shardMap('serverShards', codes, SERVER_SHARDS),
    '',
  ].join('\n');
}

function renderToolPages(codes) {
  const lines = [
    ...HEADER,
    '//',
    '// Per-locale tool-page overrides (`i18n/locales/<dir>/toolPages.ts`), consumed only by',
    '// `i18n/toolPageContent.ts`. A locale without that file falls back to English.',
    '',
  ];
  for (const code of codes) lines.push(`import ${ident(code, 'toolPages')} from "../locales/${codeToDir(code)}/toolPages";`);
  if (codes.length) lines.push('');
  lines.push('export const toolPageOverrideModules: Record<string, unknown> = {');
  for (const code of codes) lines.push(`  "${code}": ${ident(code, 'toolPages')},`);
  lines.push('};', '');
  return lines.join('\n');
}

function renderTranslatorShards(codes) {
  const lines = [
    ...HEADER,
    '//',
    '// Lazy loaders for every editable shard of every locale (MM53 translator workbench).',
    '// Imported ONLY by `lib/translator/shardSource.ts`, which loads behind the',
    '// NEXT_PUBLIC_DEPLOY_ROLE guard: production builds never reach this file.',
    '',
    'export type TranslatorShardModule = { default: Record<string, unknown> };',
    '',
    `export const TRANSLATOR_SHARD_PATHS = [${TRANSLATOR_SHARDS.map((s) => `"${s}"`).join(', ')}] as const;`,
    '',
    'export const TRANSLATOR_SHARD_LOADERS: Record<string, Record<string, () => Promise<TranslatorShardModule>>> = {',
  ];
  for (const code of codes) {
    lines.push(`  "${code}": {`);
    for (const shard of TRANSLATOR_SHARDS) lines.push(`    "${shard}": () => import("${shardPath(code, shard)}"),`);
    lines.push('  },');
  }
  lines.push('};', '');
  return lines.join('\n');
}

/**
 * Pure: the generated files for a locale list.
 * @param {{ codes: string[], defaultCode: string, toolPagesCodes: string[] }} input
 *   `codes` in `locales.ts` order; `defaultCode` the default locale;
 *   `toolPagesCodes` the subset whose locale directory ships a `toolPages.ts`.
 * @returns {Record<string, string>} repo-relative path → file content
 */
export function render({ codes, defaultCode, toolPagesCodes }) {
  if (!codes.includes(defaultCode)) throw new Error(`default locale ${defaultCode} is not registered`);
  const withToolPages = codes.filter((c) => toolPagesCodes.includes(c));
  return {
    [`${GENERATED_DIR}/resources.generated.ts`]: renderResources(defaultCode),
    [`${GENERATED_DIR}/shardLoaders.generated.ts`]: renderShardLoaders(codes),
    [`${GENERATED_DIR}/serverBundles.generated.ts`]: renderServerBundles(codes),
    [`${GENERATED_DIR}/toolPages.generated.ts`]: renderToolPages(withToolPages),
    [`${GENERATED_DIR}/translatorShards.generated.ts`]: renderTranslatorShards(codes),
  };
}

/** The `render()` input for a checkout at `root`, given the parsed locale list. */
export function collectInput(root, locales, defaultCode) {
  const codes = locales.map((l) => l.code);
  const toolPagesCodes = codes.filter((c) => existsSync(join(root, 'i18n', 'locales', codeToDir(c), 'toolPages.ts')));
  return { codes, defaultCode, toolPagesCodes };
}

async function main() {
  const { loadLocales, repoRoot } = await import('./lib/load-locales.mjs');
  const check = process.argv.includes('--check');
  const { locales, defaultLocale } = await loadLocales(repoRoot);
  const files = render(collectInput(repoRoot, locales, defaultLocale));
  const stale = [];
  for (const [rel, content] of Object.entries(files)) {
    const abs = join(repoRoot, rel);
    const current = existsSync(abs) ? readFileSync(abs, 'utf8') : null;
    if (current === content) continue;
    stale.push(rel);
    if (!check) {
      mkdirSync(dirname(abs), { recursive: true });
      writeFileSync(abs, content);
    }
  }
  if (check) {
    if (stale.length) {
      console.error(`Stale i18n registry files (run \`npm run i18n:gen\`):\n  ${stale.join('\n  ')}`);
      process.exit(1);
    }
    console.log(`i18n registry up to date (${locales.length} locales).`);
    return;
  }
  console.log(
    stale.length
      ? `Wrote ${stale.length} file(s) for ${locales.length} locales:\n  ${stale.join('\n  ')}`
      : `i18n registry already up to date (${locales.length} locales).`,
  );
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  await main();
}
